import{_ as e,o as a,c as r,X as d}from"./chunks/framework.pSp8ynCZ.js";const m=JSON.parse('{"title":"Metadata and representation: format","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-format.md","filePath":"reference-format.md"}'),o={name:"rust/api/reference-format.md"};function c(s,t,n,i,h,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="metadata-and-representation-format" tabindex="-1">Metadata and representation: format <a class="header-anchor" href="#metadata-and-representation-format" aria-label="Permalink to &quot;Metadata and representation: format&quot;">​</a></h1><p><code>cellpack::format</code> interprets the bytes written by encoders and file writers. It supplies dimensions, record extents, layout metadata and matrix directory parsing. It does not open files, allocate outputs for a whole matrix, or validate every trusted record operation.</p><h2 id="chunk-metadata" tabindex="-1">Chunk metadata <a class="header-anchor" href="#chunk-metadata" aria-label="Permalink to &quot;Chunk metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Input</th><th>Output and lifetime</th></tr></thead><tbody><tr><td><code>parse_meta</code></td><td>Chunk bytes or sufficient metadata prefix</td><td>Borrowed <code>Meta</code> after structural validation</td></tr><tr><td><code>OwnedMeta::new</code></td><td>Borrowed metadata/chunk bytes</td><td>Owned validated copy of metadata prefix</td></tr><tr><td><code>OwnedMeta::from_vec</code></td><td>Owned byte vector</td><td>Takes ownership and retains only metadata prefix</td></tr><tr><td><code>OwnedMeta::bytes / view</code></td><td>Owned metadata</td><td>Exact bytes / borrowed reusable descriptor</td></tr><tr><td><code>record_nnz</code></td><td>Record header bytes</td><td>Stored nnz decoded from the record header</td></tr></tbody></table><p>The input to <code>parse_meta</code> need not contain the entire records region, but must cover its declared metadata. Keep backing bytes immutable and alive through borrowed views. <code>OwnedMeta::view</code> does not reparse on every call.</p><h2 id="meta-queries" tabindex="-1">Meta queries <a class="header-anchor" href="#meta-queries" aria-label="Permalink to &quot;Meta queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Query</th><th>Result and units</th></tr></thead><tbody><tr><td><code>n_cells / n_dims</code></td><td>Chunk row and column counts</td></tr><tr><td><code>value_width / index_width</code></td><td>Bytes per value / per stored dimension id</td></tr><tr><td><code>renumbered / column_modes</code></td><td>Whether ids were permuted / optional raw mode values</td></tr><tr><td><code>max_nnz / max_elems / max_k / nnz_total</code></td><td>Bounds and totals used for decoding/sizing</td></tr><tr><td><code>meta_len / records_start / records_len / chunk_len</code></td><td>Byte lengths and offsets within the chunk</td></tr><tr><td><code>page_size</code></td><td>Optional packed-page size in bytes</td></tr><tr><td><code>cell_nnz / cell_layout / cell_kind</code></td><td>One local row&#39;s count/layout/encoding flags</td></tr><tr><td><code>record_range</code></td><td>Byte range relative to the records region</td></tr><tr><td><code>records_of</code></td><td>Borrowed records region from a complete chunk buffer</td></tr><tr><td><code>record</code></td><td>One record slice from its records-region buffer</td></tr></tbody></table><p>Record offsets are not file offsets. Combine them with chunk and stream offsets only at the owning storage layer. A <code>Meta</code> and records from different chunks are incompatible, even if their dimensions happen to match.</p><h2 id="matrix-stream-metadata-format-cpk" tabindex="-1">Matrix stream metadata: format::cpk <a class="header-anchor" href="#matrix-stream-metadata-format-cpk" aria-label="Permalink to &quot;Matrix stream metadata: format::cpk&quot;">​</a></h2><p><code>parse_superblock(bytes)</code> requires the 4096-byte superblock and returns a typed <code>Superblock</code>. It checks magic, version, reserved bytes, shape, dtype, page size and directory placement. It does not read the directory or payload.</p><p><code>parse_directory(super_bytes, superblock, directory_bytes)</code> verifies the directory, its hash relationship to the superblock, row coverage, stream bounds and alignment, then returns owned <code>ChunkEntry</code> values.</p><table tabindex="0"><thead><tr><th>Type</th><th>Fields and semantics</th></tr></thead><tbody><tr><td><code>Superblock</code></td><td>Page size, dtype, source layout, matrix rows/columns, chunk count/target rows, directory offset, stream length</td></tr><tr><td><code>ChunkEntry</code></td><td>First matrix row, chunk byte offset, total/meta byte lengths, chunk row count</td></tr><tr><td><code>Dtype</code></td><td>Ten numeric variants; <code>width</code> returns bytes; <code>f32</code> decodes one value and may lose precision</td></tr><tr><td><code>SourceLayout</code></td><td>Whether input arrived as CSR or dense</td></tr><tr><td><code>RecordLayout</code></td><td>Whether an individual encoded row is sparse or dense</td></tr><tr><td><code>SUPERBLOCK_LEN / ENTRY_LEN</code></td><td>4096 / 40 bytes</td></tr></tbody></table><p><code>Dtype::f32(bytes)</code> requires at least the dtype width. It converts the first value; integer values above exact <code>f32</code> range and <code>f64</code> values may round. Source layout is distinct from individual record layout.</p><p>The header/directory hash is non-cryptographic and does not cover every record payload byte. Valid structural metadata is not a guarantee that untrusted inner records are safe to decode. See <a href="/cellpack-docs/rust/api/contracts.html">trusted data</a> and the <a href="/cellpack-docs/rust/docs/format.html">binary layout reference</a>.</p><h2 id="complete-chunk-api" tabindex="-1">Complete chunk API <a class="header-anchor" href="#complete-chunk-api" aria-label="Permalink to &quot;Complete chunk API&quot;">​</a></h2><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-struct-ChunkEntry.html"><code>ChunkEntry</code></a></td><td>One chunk: rows first_row..first_row + n_rows at offset , len bytes of which the first meta_len are its metadata.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-enum-Dtype.html"><code>Dtype</code></a></td><td>Numeric type of a matrix’s values; its width is the chunks’ value width.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-enum-SourceLayout.html"><code>SourceLayout</code></a></td><td>The form a matrix arrived in.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-struct-Superblock.html"><code>Superblock</code></a></td><td>Decoded superblock fields.</td></tr></tbody></table><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-struct-Meta.html"><code>Meta</code></a></td><td>Interpretation of a chunk’s metadata bytes. Holds no data of its own: header fields are decoded once, sections are borrowed.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-struct-OwnedMeta.html"><code>OwnedMeta</code></a></td><td>Immutable metadata bytes and a validated descriptor. Views borrow only this owner; section offsets avoid self-referential pointers and lifetime extension.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-enum-RecordLayout.html"><code>RecordLayout</code></a></td><td>How a record stores its elements.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-fn-parse_meta.html"><code>parse_meta</code></a></td><td>Parses metadata from the start of bytes (the metadata alone or a whole chunk). Checks the header and section sizes; per-cell table entries are checked where they are read.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-fn-record_nnz.html"><code>record_nnz</code></a></td><td>Element count of a record from its header alone: the varint after the flags byte (0 for an empty record). For a sparse record it counts stored entries (explicit zeros included); for a dense record, non-zero values. A caller can compare it with metadata before committing to a decode.</td></tr></tbody></table><h2 id="complete-matrix-stream-api" tabindex="-1">Complete matrix-stream API <a class="header-anchor" href="#complete-matrix-stream-api" aria-label="Permalink to &quot;Complete matrix-stream API&quot;">​</a></h2><h3 id="structs-1" tabindex="-1">Structs <a class="header-anchor" href="#structs-1" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-struct-ChunkEntry.html"><code>ChunkEntry</code></a></td><td>One chunk: rows first_row..first_row + n_rows at offset , len bytes of which the first meta_len are its metadata.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-struct-Superblock.html"><code>Superblock</code></a></td><td>Decoded superblock fields.</td></tr></tbody></table><h3 id="enums-1" tabindex="-1">Enums <a class="header-anchor" href="#enums-1" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-enum-Dtype.html"><code>Dtype</code></a></td><td>Numeric type of a matrix’s values; its width is the chunks’ value width.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-enum-SourceLayout.html"><code>SourceLayout</code></a></td><td>The form a matrix arrived in.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-constant-ENTRY_LEN.html"><code>ENTRY_LEN</code></a></td><td>Bytes of one directory entry.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-constant-SUPERBLOCK_LEN.html"><code>SUPERBLOCK_LEN</code></a></td><td>Bytes reserved for the superblock at the start of the file.</td></tr></tbody></table><h3 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-fn-parse_directory.html"><code>parse_directory</code></a></td><td>Parses and checks the directory against its superblock: the hash, rows that tile 0..n_rows in order, and page-aligned, ascending, non-overlapping chunks after the superblock and before the directory.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-format-cpk-fn-parse_superblock.html"><code>parse_superblock</code></a></td><td>Parses a superblock (at least SUPERBLOCK_LEN bytes) and checks its fields against each other; the hash is checked by parse_directory .</td></tr></tbody></table>',32)])])}const p=e(o,[["render",c]]);export{m as __pageData,p as default};
